"// HandleStop parses the raw JSON payload and handles the Stop event within the execution budget.
// It returns a standard JSON object string ("{}") on completion or no-op skip.
// When the v2 spike is active and a continue is triggered, it returns
// {"decision": "continue", "reason": "<request>"} to instruct Antigravity to
// resume the agent.
func HandleStop(ctx context.Context, rawPayload []byte, opts ...HookOption) ([]byte, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	var payload StopPayload
	if len(rawPayload) > 0 && strings.TrimSpace(string(rawPayload)) != "" {
		if err := json.Unmarshal(rawPayload, &payload); err != nil {
			return nil, fmt.Errorf("parsing Stop payload JSON: %w", err)
		}
	}
	payload.Normalize()

	result, err := HandleStopEvent(ctx, &payload, opts...)
	if err != nil {
		return nil, err
	}

	// V2 spike: return continue response if the gate triggered
	if result != nil && result.V2Continue {
		resp := map[string]interface{}{
			"decision": "continue",
			"reason":   result.V2ContinueRequest,
		}
		out, err := json.Marshal(resp)
		if err != nil {
			return nil, fmt.Errorf("marshalling v2 continue response: %w", err)
		}
		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Stop continue triggered for %s (executionNum=0)\n", payload.ConversationID)
		return out, nil
	}

	return []byte("{}"), nil
}"

